  name                        = "trip-booking-bot"
  description                 = "Bot for booking trips"
  role_arn                    = aws_iam_role.lex_bot_role.arn
  data_privacy                  = true
  child_directed                = false
  idle_session_ttl_in_seconds   = 300
  locale                        = "en-US"
  clarification_prompt {
    max_attempts = 2
    messages = [
      {
        content      = "I'm sorry, I didn't understand. Please try again."
        content_type = "PlainText"
      }
    ]
  }
  failure_url = "https://example.com/failure"
  success_url = "https://example.com/success"
  abort_statement {
    messages = [
      {
        content      = "I'm sorry, I'm having trouble understanding. Please try again."
        content_type = "PlainText"
      }
    ]
  }
  process_behavior = "SAVE"
  intent {
    intent_name = "BookTripIntent"
    sample_utterances = [
      "I want to book a trip",
      "Book me a flight",
      "Schedule a vacation"
    ]
    slots = [
      {
        name     = "Destination"
        slot_type = "AMAZON.US_CITY"
        sample_utterances = [
          "to {Destination}",
          "to the city of {Destination}"
        ]
        prompt_max_attempts = 2
        prompt_message {
          content      = "Where would you like to go?"
          content_type = "PlainText"
        }
        required = true
      },
      {
        name     = "StartDate"
        slot_type = "AMAZON.DATE"
        sample_utterances = [
          "starting {StartDate}",
          "from {StartDate}"
        ]
        prompt_max_attempts = 2
        prompt_message {
          content      = "When would you like to start your trip?"
          content_type = "PlainText"
        }
        required = true
      },
      {
        name     = "EndDate"
        slot_type = "AMAZON.DATE"
        sample_utterances = [
          "ending {EndDate}",
          "until {EndDate}"
        ]
        prompt_max_attempts = 2
        prompt_message {
          content      = "When would you like to end your trip?"
          content_type = "PlainText"
        }
        required = true
      }
    ]
    confirmation_prompt {
      max_attempts = 2
      messages = [
        {
          content      = "Just to confirm, you want to book a trip from {StartDate} to {EndDate} to {Destination}. Is that correct?"
          content_type = "PlainText"
        }
      ]
    }
    fulfillment_activity {
      type = "ReturnIntent"
    }
  }
  intent {
    intent_name = "CancelBookingIntent"
    sample_utterances = [
      "Cancel my booking",
      "I want to cancel",
      "Cancel trip"
    ]
    fulfillment_activity {
      type = "ReturnIntent"
    }
  }
  intent {
    intent_name = "HelpIntent"
    sample_utterances = [
      "Help",
      "What can you do?",
      "Tell me about your services"
    ]
    fulfillment_activity {
      type = "ReturnIntent"
    }
  }
}

