  iam_role_arn         = aws_iam_role.flow.arn
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "main" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = false

  tags = {
    Name = "main-subnet"
  }
}

resource "aws_security_group" "main" {
  name        = "main"
  description = "managed security group"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "app traffic from within VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "egress within VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }
}

resource "aws_elb" "main" {
  name               = "main-elb"
  internal           = true
  security_groups    = [aws_security_group.main.id]
  subnets            = [aws_subnet.main.id]
  idle_timeout       = 30
  connection_draining = true

  access_logs {
    bucket        = aws_s3_bucket.log_bucket.id
    bucket_prefix = "elb-logs"
    enabled       = true
  }

  listener {
    instance_port     = 443
    instance_protocol = "HTTPS"
    lb_port           = 443
    lb_protocol       = "HTTPS"
    ssl_certificate_id = "arn:aws:acm:us-east-1:123456789012:certificate/12345678-1234-1234-1234-123456789012"
  }

  health_check {
    target              = "HTTPS:443/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 2
  }
}

resource "aws_elastic_beanstalk_application" "app" {
  name        = "my-app"
  description = "My application"

  appversion_lifecycle {
    service_role = aws_iam_role.eb_service.arn
  }
}

resource "aws_iam_role" "eb_service" {
  name = "elasticbeanstalk-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "elasticbeanstalk.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_db_instance" "main" {
  identifier             = "my-db"
  engine                 = "mysql"
  engine_version         = "8.0"
  instance_class         = "db.t3.micro"
  allocated_storage      = 20
  storage_encrypted      = true
  kms_key_id             = aws_kms_key.main.arn
  iam_database_authentication_enabled = true
  deletion_protection    = true
  performance_insights_enabled = true
  performance_insights_kms_key_id = aws_kms_key.main.arn
  backup_retention_period = 7
  multi_az               = true
  db_subnet_group_name   = aws_db_subnet_group.main.name

  username = "admin"
  password = "securepassword123"

  tags = {
    Name = "my-db"
  }
}

resource "aws_db_subnet_group" "main" {
  name       = "main-db-subnet-group"
  subnet_ids = [aws_subnet.main.id]

  tags = {
    Name = "main-db-subnet-group"
  }
}

