      {
        Action = "logs:PutLogEvents"
        Resource = "arn:aws:logs:${aws_region}:${aws_account_id}:log-group:/aws/lambda/*"
        Effect   = "Allow"
      },
      {
        Action = "s3:GetObject"
        Resource = "${aws_s3_bucket.cat_pictures.arn}/*"
        Effect   = "Allow"
      },
