  signing_behavior                   = "always"
  signing_protocol                   = "sigv4"

  s3 {
    bucket_head_method              = "GET"
    bucket_bucket                      = aws_s3_bucket.video_streaming_bucket.id
  }
}

resource "aws_cloudfront_distribution" "video_streaming_distribution" {
  depends_on      = [aws_cloudfront_origin_access_control.video_streaming_oac]
  origin {
    domain_name = aws_s3_bucket.video_streaming_bucket.bucket_regional_domain_name
    origin_id   = "S3-video-streaming-bucket"

    s3_origin_config {
      origin_access_identity = aws_cloudfront_origin_access_control.video_streaming_oac.id
    }
  }

  enabled             = true
  is_ipv6_enabled     = true
  comment            = "Distribution for video streaming site"
  default_root_object = "index.html"

  aliases = ["video-streaming-site.com"]

  viewer_certificate {
    cloudfront_default_certificate = true
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }
}

resource "aws_route53_zone" "video_streaming_zone" {
  name        = "video-streaming-site.com"
