  name           = "video-streaming-site.com"
  type           = "A"

  alias {
    name                   = aws_cloudfront_distribution.video_streaming_distribution.domain_name
    zone_id               = aws_cloudfront_distribution.video_streaming_distribution.id
    evaluate_target_health = true
  }
}

resource "aws_vpc" "video_streaming_vpc" {
  cidr_block = "10.0.0.0/16"
}

output "cloudfront_distribution_domain_name" {
  value       = aws_cloudfront_distribution.video_streaming_distribution.domain_name
}

