terraform {
  required_version = ">= 1.6.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.60"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_kms_key" "main" {
  description             = "customer managed key"
  enable_key_rotation     = true
  deletion_window_in_days = 7
}

resource "aws_cloudwatch_log_group" "example" {
  name              = "example-logs"
  retention_in_days = 365
  kms_key_id        = aws_kms_key.main.arn
}

resource "aws_iam_role" "flow" {
  name               = "vpc-flow-role"
  assume_role_policy = jsonencode({ Version = "2012-10-17", Statement = [{
    Effect = "Allow", Principal = { Service = "vpc-flow-logs.amazonaws.com" }, Action = "sts:AssumeRole" }] })
}

resource "aws_flow_log" "vpc" {
  vpc_id               = aws_vpc.main.id
  traffic_type         = "ALL"
  log_destination_type = "cloud-watch-logs"
  log_destination      = aws_cloudwatch_log_group.example.arn
  iam_role_arn         = aws_iam_role.flow.arn
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "private_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-east-1a"

  map_public_ip_on_launch = false

  tags = {
    Name = "private-a"
  }
}

resource "aws_subnet" "private_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-east-1b"

  map_public_ip_on_launch = false

  tags = {
    Name = "private-b"
  }
}

resource "aws_security_group" "main" {
  name        = "main"
  description = "managed security group"
  vpc_id      = aws_vpc.main.id
  ingress {
    description = "app traffic from within VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }
  egress {
    description = "egress within VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }
}

resource "aws_db_subnet_group" "main" {
  name       = "main-db-subnet-group"
  subnet_ids = [aws_subnet.private_a.id, aws_subnet.private_b.id]

  tags = {
    Name = "main-db-subnet-group"
  }
}

resource "aws_rds_cluster" "main" {
  cluster_identifier      = "my-cluster"
  engine                  = "aurora-mysql"
  engine_version          = "8.0.mysql_aurora.3.05.2"
  master_username         = "admin"
  master_password         = random_password.db_master_password.result
  backup_retention_period = 7
  preferred_backup_window = "01:00-02:00"
  storage_encrypted       = true
  kms_key_id              = aws_kms_key.main.arn
  deletion_protection     = true
  vpc_security_group_ids  = [aws_security_group.main.id]
  db_subnet_group_name    = aws_db_subnet_group.main.name
  iam_database_authentication_enabled = true
  performance_insights_enabled        = true
  performance_insights_kms_key_id     = aws_kms_key.main.arn

  serverlessv2_scaling_configuration {
    min_capacity = 0.5
    max_capacity = 2.0
  }

  tags = {
    Name = "my-cluster"
  }
}

resource "random_password" "db_master_password" {
  length  = 16
  special = true
}

resource "aws_secretsmanager_secret" "db_creds" {
  name        = "rds-credentials"
  description = "Database credentials for RDS cluster"
  kms_key_id  = aws_kms_key.main.arn

  tags = {
    Name = "rds-credentials"
  }
}

resource "aws_secretsmanager_secret_version" "db_creds" {
  secret_id     = aws_secretsmanager_secret.db_creds.id
  secret_string = jsonencode({
    username = aws_rds_cluster.main.master_username
    password = random_password.db_master_password.result
  })
}

resource "aws_iam_role" "rds_proxy" {
  name = "rds-proxy-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "rds_proxy" {
  name = "rds-proxy-policy"
  role = aws_iam_role.rds_proxy.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue"
        ]
        Resource = aws_secretsmanager_secret.db_creds.arn
      }
    ]
  })
}

resource "aws_db_proxy" "main" {
  name                    = "my-proxy"
  role_arn                = aws_iam_role.rds_proxy.arn
  vpc_security_group_ids  = [aws_security_group.main.id]
  vpc_subnet_ids          = [aws_subnet.private_a.id, aws_subnet.private_b.id]
  debug_logging           = false
  idle_client_timeout     = 1800
  engine_family           = "MYSQL"

  auth {
    username = aws_rds_cluster.main.master_username
    secret_arn = aws_secretsmanager_secret.db_creds.arn
  }

  tags = {
    Name = "my-proxy"
  }
}

resource "aws_db_proxy_target" "main" {
  db_proxy_name    = aws_db_proxy.main.name
  db_cluster_identifier = aws_rds_cluster.main.id
}

